import { ICloudbase } from '@cloudbase/types'
import { RealtimeWebSocketClient } from './websocket-client'
import { setWsClass, setRuntime } from './common'
import { ICloudbaseComponent, ICloudbaseHook } from '@cloudbase/types/component'

declare const cloudbase: ICloudbase

const hook: ICloudbaseHook = {
  target: 'database',
  entity() {
    const { adapter, runtime } = this.platform
    setWsClass(adapter.wsClass)
    setRuntime(runtime)
  },
}

const component: ICloudbaseComponent = {
  name: 'realtime',
  IIFE: true,
  entity() {
    this.prototype.wsClientClass = RealtimeWebSocketClient
  },
}

try {
  cloudbase.registerComponent(component)
  cloudbase.registerHook(hook)
} catch (e) {}

export function registerRealtime(app: Pick<ICloudbase, 'registerComponent'|'registerHook'>) {
  try {
    app.registerComponent(component)
    app.registerHook(hook)
  } catch (e) {
    console.warn(e)
  }
}

/**
 * 导出 RealtimeWebSocketClient，供直接使用 @cloudbase/database（不经完整 js-sdk）
 * 且需要 watch 实时推送的场景手动注入：
 *
 *   const { Db } = require('@cloudbase/database')
 *   const { RealtimeWebSocketClient } = require('@cloudbase/realtime')
 *   Db.wsClientClass = RealtimeWebSocketClient
 *
 * 背景：@cloudbase/database 1.5.0 起 realtime 实现不再内联（抽离为独立模块），
 * watch() 依赖 wsClientClass 注入，未注入时抛出明确错误。
 */
export { RealtimeWebSocketClient }
